// agent-guard plugin for OpenCode (generated by `guard install` from
// templates/opencode-plugin.js in the agent-guard repo; edit it there).
// After each shell command or file edit it asks agent-guard to check the change
// and appends any warning to the tool result, so the model sees it. Warn-only:
// it never changes what the tool did and never fails the call.
//
// Written for OpenCode's plugin API with a default export { id, setup(ctx) } and
// ctx.tool.hook("execute.after", ...) (OpenCode 2.x).
import { spawnSync } from "node:child_process";
import path from "node:path";

const GUARD = "__GUARD_BIN__";
const AGENT = "__AGENT__";
const SHELL_TOOLS = new Set(["shell", "bash"]);
const EDIT_TOOLS = new Set(["write", "edit", "multiedit"]);
const PATCH_TOOLS = new Set(["patch", "apply_patch"]);

function guard(payload) {
  try {
    const r = spawnSync(GUARD, ["hook", "--agent", AGENT, "--format", "generic"], {
      input: JSON.stringify(payload),
      encoding: "utf8",
      timeout: 15000,
    });
    return JSON.parse(r.stdout || "{}");
  } catch {
    return {};
  }
}

function fileOf(input) {
  return input?.path ?? input?.filePath ?? input?.file_path ?? null;
}

// Same rule OpenCode uses to turn a tool result into model-visible content.
function contentOf(result) {
  const c = result?.content;
  if (typeof c === "string") return [{ type: "text", text: c }];
  if (Array.isArray(c) && c.length > 0) return [...c];
  const o = result?.output;
  if (o === undefined) return [];
  if (typeof o === "string") return [{ type: "text", text: o }];
  try {
    return [{ type: "text", text: JSON.stringify(o) ?? String(o) }];
  } catch {
    return [{ type: "text", text: String(o) }];
  }
}

// The OpenCode server can serve several projects and runs in its own folder, so relative paths resolve
// against the session's directory, not process.cwd().
export function payloadFor(event, sessionDir) {
  const tool = String(event?.tool ?? "").toLowerCase();
  const input = event?.input ?? {};
  const base = { session_id: event?.sessionID ?? "" };
  const dir = input.workdir || sessionDir || process.cwd();
  if (SHELL_TOOLS.has(tool)) {
    return { ...base, event: "post_command", command: String(input.command ?? ""), cwd: dir };
  }
  if (EDIT_TOOLS.has(tool)) {
    const raw = fileOf(input);
    const file = raw ? path.resolve(dir, raw) : null;
    const text = input.content ?? input.newString ?? null;
    return {
      ...base,
      event: "post_edit",
      cwd: file ? path.dirname(file) : dir,
      files: file ? [file] : [],
      edits: file && typeof text === "string" ? { [file]: text } : {},
    };
  }
  if (PATCH_TOOLS.has(tool)) {
    // A patch can touch several files; check whatever changed in the repo since the last hook.
    return { ...base, event: "post_command", command: "", cwd: dir };
  }
  return null;
}

const sessionDirs = new Map();

async function sessionDirectory(ctx, sessionID) {
  if (!sessionID) return null;
  if (sessionDirs.has(sessionID)) return sessionDirs.get(sessionID);
  try {
    const s = await ctx.session.get({ sessionID });
    const dir = s?.location?.directory ?? s?.data?.location?.directory ?? null;
    if (dir) sessionDirs.set(sessionID, dir);
    return dir;
  } catch {
    return null;
  }
}

export async function afterTool(event, ctx) {
  try {
    if (!event || event.status !== "completed" || !event.result) return;
    const payload = payloadFor(event, await sessionDirectory(ctx, event.sessionID));
    if (!payload) return;
    const res = guard(payload);
    if (!res.agent) return;
    event.result = { ...event.result, content: [...contentOf(event.result), { type: "text", text: res.agent }] };
  } catch {
    // agent-guard must never break a tool call
  }
}

export default {
  id: "agent-guard",
  setup: async (ctx) => {
    await ctx.tool.hook("execute.after", (event) => afterTool(event, ctx));
  },
};
